from pathlib import Path
import math
root=Path(__file__).parent

def btn(s, cls=''): return f'<button class="{cls}">{s}</button>'
def field(label,value,cls=''): return f'<div class="field {cls}"><small>{label}</small><strong>{value}</strong></div>'
def wave(color='#acd0ff', w=800,h=150,phase=0,grid=True):
    pts=' '.join(f'{i*w/120:.1f},{(h/2-(h/2-18)*math.cos(2*math.pi*(i/120+phase))):.1f}' for i in range(121))
    lines=''.join(f'<path d="M{x*w/4},0V{h}"/>' for x in range(5))+''.join(f'<path d="M0,{y*h/4}H{w}"/>' for y in range(5))
    return f'<svg viewBox="0 0 {w} {h}" class="wave" fill="none"><g stroke="currentColor" opacity=".13">{lines if grid else ""}</g><polyline points="{pts}" stroke="{color}" stroke-width="3"/><circle cx="{w*.25}" cy="{h/2}" r="6" fill="{color}"/></svg>'
def stage(dark=True):
    ink='#c3d4e0' if dark else '#7a8d88'
    spots=''
    for i,a in enumerate([1,.58,.16,.58]):
        x=130+i*170
        spots+=f'<ellipse cx="{x}" cy="178" rx="62" ry="19" fill="#edf9ff" opacity="{a*.6}"/><path d="M{x-8},35 L{x+8},35 L{x+62},178 Q{x},197 {x-62},178Z" fill="url(#beam)" opacity="{a}"/><rect x="{x-16}" y="24" width="32" height="24" rx="6" fill="{ink}"/><text x="{x}" y="225" text-anchor="middle" fill="{ink}" font-family="-apple-system,sans-serif" font-size="20">Wash 0{i+1}</text>'
    return f'<svg viewBox="0 0 780 245" class="stage"><defs><linearGradient id="beam" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#edf9ff" stop-opacity=".04"/><stop offset="1" stop-color="#edf9ff" stop-opacity=".72"/></linearGradient></defs><path d="M20 200L105 105H675L760 200Z" fill="none" stroke="{ink}" opacity=".28"/>{spots}</svg>'
def poolitem(n,title,sub='',active=False): return f'<div class="poolitem {"active" if active else ""}"><span class="number">{n}</span><div><b>{title}</b><small>{sub}</small></div></div>'
