norman=f'''<section class="proposal norman" id="norman"><header class="toolbar"><h1 class="grow">Palettes & phasers</h1><div class="flow-title">Select fixtures <span>→</span> <b>Build the effect</b> <span>→</span> Store & apply</div></header><div class="content"><aside class="rail"><div class="section-label">Selection</div><h2>4 wash fixtures</h2><p class="instruction">This effect will apply only to these fixtures.</p>{''.join(f'<div class="fixture-row"><span class="check">✓</span>Wash 0{i}</div>' for i in range(1,5))}<div style="margin-top:24px">{btn('Change selection','subtle')}</div><div style="margin-top:40px"><div class="section-label">Palette pool</div>{poolitem('◐','Dimmer','Brightness only',True)}{poolitem('◉','Color')}{poolitem('⌖','Position')}{poolitem('▦','All')}</div></aside><main><div class="row between"><div class="section-label">Dimmer palette</div><span class="tag" style="background:#e3e9dd;color:#235846">Stored</span></div><h2>Dimmer wave</h2><p class="instruction">Fade from Full to Blackout, then repeat.</p><div class="step active"><span class="num">1</span><div class="grow"><b>Full · 100%</b><small>Linked to the Full palette</small></div><span class="chevron">⌄</span></div><div class="step"><span class="num">2</span><div class="grow"><b>Blackout · 0%</b><small>Linked to the Blackout palette</small></div><span class="chevron">⌄</span></div>{btn('＋ Add a step','quiet')}<div class="timing"><h3 style="margin-bottom:18px">How it moves</h3><div class="grid2">{field('Speed','60 BPM')}{field('Repeat every','4 beats')}{field('Fixture phase','0–360°')}{field('Transition','Smooth · 100%')}</div><div class="row between" style="margin-top:20px"><small>Equal step lengths</small>{btn('Edit timing','quiet')}</div></div></main><aside class="outcome"><div class="row between"><h3>What you’ll see</h3><span>Ⅱ</span></div><small>Live preview · 4-second cycle</small><div class="output-bars">{''.join(f'<div data-label="0{i+1}" style="height:{h}%"></div>' for i,h in enumerate([100,55,10,55]))}</div><dl><dt>Changes</dt><dd>Dimmer intensity</dd><dt>Preserves</dt><dd>Color, position and beam</dd><dt>Step sources</dt><dd>Full + Blackout</dd></dl><div class="status"><b>Ready to apply</b><p style="margin-top:9px">Your fixtures keep their current look until you apply.</p></div></aside></div><footer class="footer"><div class="grow"><b>Dimmer wave</b><small>Stored palette · Applies to Wash 01–04</small></div>{btn('Update palette','subtle')}{btn('Apply to 4 fixtures','primary')}</footer></section>'''
# Cooper
cooper=f'''<section class="proposal cooper" id="cooper"><header class="toolbar">{btn('‹ Palette library','quiet')}<span class="grow"></span><span class="tag">Dimmer</span><span class="muted">4 wash fixtures</span>{btn('Change selection')}</header><div class="workspace"><main class="canvas"><div class="row between"><div><small style="margin-bottom:7px">Palettes & phasers</small><h2>Build a dimmer wave</h2></div><span class="tag">Live preview</span></div><div class="scene"><div class="row between"><span>Wash 01–04</span><span>Ⅱ Pause</span></div>{stage()}</div><div><div class="row between" style="margin-bottom:16px"><h3>Two looks, one repeating effect</h3>{btn('＋ Add step','quiet')}</div><div class="recipe"><div class="step"><span class="num">1</span><div><b>Full</b><small>Linked palette · 100%</small></div><span class="grow"></span><span>⌄</span></div><span class="muted">→</span><div class="step"><span class="num">2</span><div><b>Blackout</b><small>Linked palette · 0%</small></div><span class="grow"></span><span>⌄</span></div></div></div><div class="preview-wave"><div class="row between"><small>One cycle</small><small>4 seconds</small></div>{wave('#def49b',780,85,0,False)}</div><small>Only dimmer changes. Color, position and beam stay as they are.</small></main><aside class="inspector"><div><div class="section-label">Start with a pattern</div><div class="pattern on">{wave('#def49b',90,28,0,False)}<b>Wave</b></div><div class="pattern">{wave('#9baeb0',90,28,.25,False)}Breathe</div><div class="pattern"><svg viewBox="0 0 90 28"><path d="M1 25H20V4H43V25H64V4H89" fill="none" stroke="#9baeb0" stroke-width="2"/></svg>Pulse</div></div><div><div class="section-label">Speed</div><div class="row"><span class="tempo">60</span><span class="muted">BPM</span><span class="grow"></span><span>− &nbsp; ＋</span></div><div class="line"></div></div><div><div class="section-label">Fixture rhythm</div><div class="distribution">{btn('Together')}{btn('Wave →','selected')}{btn('← Reverse')}</div></div>{field('Cycle length','4 beats')}<div class="divider"></div><div class="row between"><span>Advanced timing</span><span>⌄</span></div><small>Step width, transition<br>and phase offset</small></aside></div><footer class="footer"><div class="name"><small>Palette name</small><b>Dimmer wave</b></div><span class="grow"></span>{btn('Store palette')}{btn('Store & apply to 4','primary')}</footer></section>'''
# Victor: a score with four phase-offset traces and a movable playhead
w,h=590,340
traces=''
for i in range(4):
    y=26+i*81
    pts=' '.join(f'{38+x*530/120:.1f},{y+26-24*math.cos(2*math.pi*(x/120-i/4)):.1f}' for x in range(121))
    traces+=f'<text x="0" y="{y+30}" font-size="14" fill="#7a827b">0{i+1}</text><path d="M38 {y+53}H578" stroke="#d4d9cd"/><polyline points="{pts}" stroke="{("#ad4f29" if i==1 else "#577576")}" stroke-width="{3 if i==1 else 2}" fill="none"/>'
    cy=y+26-24*math.cos(2*math.pi*(.35-i/4))
    traces+=f'<circle cx="223.5" cy="{cy}" r="6" fill="#ad4f29" stroke="#f6f2e9" stroke-width="2"/>'
score=f'<svg viewBox="0 0 590 360" width="100%"><g fill="none" stroke="#d9ddd1">'+''.join(f'<path d="M{38+i*132.5} 0V340" stroke-dasharray="3 5"/>' for i in range(5))+f'</g><rect x="38" y="0" width="265" height="340" fill="#e4e9df" opacity=".42"/>{traces}<path d="M223.5 0V341" stroke="#ad4f29" stroke-width="1.5"/><path d="M216 -1h15l-7.5 9Z" fill="#ad4f29"/>'+''.join(f'<text x="{38+i*132.5}" y="359" text-anchor="middle" font-size="14" fill="#7a827b">{i}</text>' for i in range(5))+'</svg>'
phase='<svg viewBox="0 0 210 180"><circle cx="105" cy="90" r="63" fill="none" stroke="#d3d9ce" stroke-width="18"/><path d="M105 27 A63 63 0 1 1 42 90" fill="none" stroke="#ad4f29" stroke-width="3"/>'
for i,(x,y) in enumerate([(105,27),(168,90),(105,153),(42,90)]): phase+=f'<circle cx="{x}" cy="{y}" r="13" fill="#f6f2e9" stroke="#ad4f29" stroke-width="2"/><text x="{x}" y="{y+4}" text-anchor="middle" font-size="11" fill="#ad4f29">0{i+1}</text>'
phase+='<text x="105" y="88" text-anchor="middle" font-size="26" fill="#283437">360°</text><text x="105" y="107" text-anchor="middle" font-size="12" fill="#7a827b">phase spread</text></svg>'
victor=f'''<section class="proposal victor" id="victor"><header class="toolbar"><h1>Light score</h1><span class="tag" style="background:#e6e8df">Dimmer wave</span><span class="grow"></span>{btn('↶ Undo','quiet')}{btn('Ⅱ Pause')}{btn('↺ Restart','quiet')}</header><div class="sentence">Make <span class="editable">4 wash fixtures</span> flow from <span class="editable">Full</span> to <span class="editable">Blackout</span>,<br>repeating every <span class="editable">4 beats</span> at <span class="editable">60 BPM</span>.</div><div class="work"><aside class="sources"><div class="section-label">Palette sources</div><div class="source"><div class="swatch"></div><b>Full</b><small>Dimmer · 100%</small><small style="margin-top:10px;color:#ad4f29">↗ Linked to step 1</small></div><div class="source off"><div class="swatch"></div><b>Blackout</b><small>Dimmer · 0%</small><small style="margin-top:10px;color:#ad4f29">↗ Linked to step 2</small></div>{btn('＋ Add source','quiet')}<p class="edit-help" style="margin-top:26px">Drop a palette on a step to change its source.</p></aside><main class="plot"><div class="row between"><h3>Every fixture. Every moment.</h3><span class="tag" style="background:#e9e6dc">1.4 s / 4 s</span></div><div class="row between" style="margin:12px 12px 15px 40px"><small>Step 1 · Full</small><small>Step 2 · Blackout</small></div>{score}<div class="row between" style="margin:14px 0 0 36px"><small>Beats</small><small>Drag the playhead to inspect</small></div><div class="row" style="background:#ebe4d9;border-left:3px solid #ad4f29;padding:15px 19px;margin:24px 0 0 36px"><span style="color:#ad4f29">●</span><b>Wash 02</b><span class="grow"></span><span>90% at 1.4 s</span></div></main><aside class="phase"><h3>Spread the fixtures</h3>{phase}<p class="edit-help">Drag a fixture around the ring to shift its phase.</p><div class="divider"></div><h3>At this moment</h3><div class="mini-outputs"><div style="opacity:.2"></div><div style="opacity:.9"></div><div style="opacity:.8"></div><div style="opacity:.1"></div></div><div class="row between" style="font-size:12px;color:#7a827b;padding:0 8px"><span>01</span><span>02</span><span>03</span><span>04</span></div><small>Dimmer only<br>Other attributes stay unchanged.</small></aside></div><footer class="footer"><div class="grow"><b>Dimmer wave</b><small>2 linked steps · 4 selected fixtures</small></div>{btn('Store palette')}{btn('Store & apply','primary')}</footer></section>'''
styles += """
.norman button.primary{background:#235846;color:#fff}.norman .content{padding-top:12px;padding-bottom:24px}.norman .fixture-row{padding:12px 0}.norman .rail .poolitem{padding:12px;min-height:54px}.norman .rail .poolitem small{font-size:13px}.norman .instruction{margin-bottom:18px}.norman .step{min-height:84px;padding:13px 18px}.norman .timing{margin-top:16px;padding-top:18px}.norman .timing .field{padding:12px 16px;min-height:70px}.norman .outcome{padding:23px;gap:16px}.norman .outcome .status{font-size:15px}.norman .outcome dd{font-size:17px}
.cooper .canvas{gap:20px;padding-top:26px}.cooper .scene{min-height:245px}.cooper .scene .stage{height:180px}.cooper .inspector{gap:17px;padding-top:26px}.cooper .pattern{padding:14px 17px;margin-bottom:8px}.cooper .preview-wave .wave{height:75px}
.victor .plot>svg{display:block;width:100%;height:340px}.victor .phase{gap:16px}.victor .phase svg{height:160px}.victor .mini-outputs{height:64px}.victor .plot .row{margin-bottom:16px}.victor .footer{background:#f6f2e9;position:relative;z-index:1}
"""
html='<!doctype html><meta charset="utf-8"><title>Palette editor proposals</title><style>'+styles+'</style>'+apple+console+norman+cooper+victor
(root/'panels.html').write_text(html)
